INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('182be334-906b-447c-8bb7-7be26c2ed328', '0b8ddab7-b106-4873-bc4d-3987421d265d', 1, 'O Despertar Sagrado', NULL, '{"intro": "O primeiro pensamento do dia \u00e9 a semente de todas as suas a\u00e7\u00f5es.", "prayer": "Ofere\u00e7a o seu dia antes de sair da cama.", "practice": "N\u00e3o pegue no celular nos primeiros 15 minutos do dia.", "reflection": "A forma como voc\u00ea come\u00e7a o dia determina a sua alma.", "journal_prompt": "Qual \u00e9 a primeira coisa que voc\u00ea entrega ao mundo ao acordar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;